c1657.try_sql:
-- The second COMMENT overwrites the first, and IS '' removes the comment
CREATE TABLE lab_c1657_t (id NUMBER);
COMMENT ON TABLE lab_c1657_t IS 'stary opis';
COMMENT ON TABLE lab_c1657_t IS 'nowy opis';
SELECT comments FROM user_tab_comments WHERE table_name = 'LAB_C1657_T';
COMMENT ON TABLE lab_c1657_t IS '';
SELECT NVL(comments, '(brak)') AS comments FROM user_tab_comments WHERE table_name = 'LAB_C1657_T';

