CREATE TABLE lab_c1660_emp AS SELECT employee_id, salary FROM employees;
CREATE INDEX lab_c1660_ix ON lab_c1660_emp (salary * 12);
SELECT index_name, index_type FROM user_indexes WHERE index_name = 'LAB_C1660_IX';
SELECT column_name FROM user_ind_columns WHERE index_name = 'LAB_C1660_IX';
SELECT column_expression FROM user_ind_expressions WHERE index_name = 'LAB_C1660_IX';

